// The real app model with a stand-in engine: queueing, failing, stopping, restarting, cleaning up. Run by test.sh with DOCKSIDE_ROOT set to a throwaway folder.
import SwiftUI
var np = 0, nf = 0
func check(_ c: Bool, _ m: String) { if c { np += 1 } else { nf += 1; print("FAIL", m) } }
let fm = FileManager.default, root = Paths.root
precondition(root.path.contains("/T/") || root.path.contains("/tmp"), "only in a throwaway folder")
UserDefaults.standard.removePersistentDomain(forName: ProcessInfo.processInfo.processName)
func wait(_ t: Double = 20, _ f: () -> Bool) -> Bool { let e = Date().addingTimeInterval(t); while Date() < e { if f() { return true }; RunLoop.main.run(until: Date().addingTimeInterval(0.03)) }; return f() }
func put(_ p: String, _ s: String = "x") -> URL { let u = root.appendingPathComponent(p); try! fm.createDirectory(at: u.deletingLastPathComponent(), withIntermediateDirectories: true); try! s.write(to: u, atomically: true, encoding: .utf8); return u }
func game(_ m: Model, _ id: String) -> Game? { m.games.first { $0.titleID == id } }
func id(_ n: Int) -> String { String(format: "0100%08X000", n + 16) + "0" }
func nsp(_ n: Int, _ mode: String = "ok") -> URL { put("dump/Game \(n) [\(id(n))][v0].nsp", mode) }
func log() -> [String] { ((try? String(contentsOf: root.appendingPathComponent("engine.log"), encoding: .utf8)) ?? "").split(separator: "\n").map(String.init) }
func queueUp(_ m: Model, _ n: Int, _ mode: String = "ok", after: After = .ask) -> Bool { m.after = after; m.review = Review(parts: []); m.review.add([nsp(n, mode)]); m.reviewPlace = Paths.games; return m.convert() }
_ = put("prod.keys", "k = 1")
let m = Model(); check(wait(60) { m.ready }, "ready with the stand-in tools: " + m.checks.filter { !$0.ok }.map(\.title).joined(separator: ", "))
// three in a row, one failing
check(queueUp(m, 1) && m.builder.running, "the first starts at once"); check(queueUp(m, 2, "fail") && queueUp(m, 3) && m.queue.waiting.count == 2, "two wait"); check(!queueUp(m, 3) && m.reviewNote?.contains("already in the queue") == true, "not twice"); check(m.builder.remaining() != nil && m.queueTime(m.builder.remaining()!) > m.builder.remaining()! + 800, "time for all of them")
check(wait { !m.builder.running && m.queue.waiting.isEmpty && m.queue.current == nil }, "all run"); check(log().filter { $0.hasPrefix("start") } == ["start \(id(1))", "start \(id(2))", "start \(id(3))"] && !log().contains("overlap"), "in order, never two at once"); check(m.queue.problems.map(\.title) == ["Game 2"] && m.queue.problems[0].reason.contains("broken on purpose"), "the failure is kept, with its reason"); check(game(m, id(1)) != nil && game(m, id(3)) != nil && m.offers.count == 2, "both are ready")
check(fm.fileExists(atPath: Paths.games.path + "/\(id(1))_build"), "asked: leftovers stay")
// cleaning up by choice
m.queue.problems = []; m.cleanUp(game(m, id(1))); check(wait { m.cleaning?.ready == true }, "measured"); check(m.cleaning!.items.count == 3 && m.cleaning!.items.map(\.on) == [true, false, false], "leftovers chosen; originals and keys not"); m.doCleanUp(m.cleaning!); check(wait { !m.removing }, "removed"); check(!fm.fileExists(atPath: Paths.games.path + "/\(id(1))_build") && fm.fileExists(atPath: root.path + "/dump/Game 1 [\(id(1))][v0].nsp") && game(m, id(1)) != nil && !m.offers.contains { $0.titleID == id(1) }, "only the leftovers went"); check(fm.fileExists(atPath: Paths.games.path + "/\(id(3))_build"), "not another game's")
// chosen beforehand
check(queueUp(m, 4, after: .leftovers) && wait { m.queue.current == nil && !m.removing && game(m, id(4)) != nil }, "converts"); check(wait { !fm.fileExists(atPath: Paths.games.path + "/\(id(4))_build") } && fm.fileExists(atPath: root.path + "/dump/Game 4 [\(id(4))][v0].nsp") && !m.offers.contains { $0.titleID == id(4) }, "leftovers go by themselves, originals stay")
check(queueUp(m, 5, "linked", after: .everything) && wait { m.queue.current == nil && !m.removing && !m.builder.running && game(m, id(5)) != nil }, "a game that still needs its leftovers"); check(wait { m.queue.problems.contains { $0.reason.contains("still uses") } } && fm.fileExists(atPath: Paths.games.path + "/\(id(5))_build") && fm.fileExists(atPath: root.path + "/dump/Game 5 [\(id(5))][v0].nsp"), "nothing of it is removed"); m.queue.problems = []
m.cleanUp(nil); check(wait { m.cleaning?.ready == true }, "everything measured"); check(m.cleaning!.items.contains { if case .keys = $0.kind { return !$0.on && $0.blocked == nil }; return false } && m.cleaning!.items.filter { $0.game?.titleID == id(5) }.contains { $0.blocked != nil }, "keys offered, never chosen; the linked one refused"); m.cleaning = nil
// stopping pauses; continuing goes on
check(queueUp(m, 6, "slow") && queueUp(m, 7), "two more"); check(wait { log().contains("start \(id(6))") }, "running"); m.cleanUp(nil); _ = wait { m.cleaning?.ready == true }; check(!m.cleaning!.items.contains { if case let .leftovers(l) = $0.kind { return [id(6), id(7)].contains(l.id) }; return false } && m.cleaning!.items.contains { if case .keys = $0.kind { return $0.blocked != nil }; return false }, "what is converting, and the keys it needs, are left out"); m.cleaning = nil
m.builder.cancel(); check(wait { !m.builder.running } && m.queue.paused && m.queue.waiting.count == 1 && !log().contains("start \(id(7))"), "stopped: the rest wait"); m.resumeQueue(); check(wait { game(m, id(7)) != nil && m.queue.current == nil }, "continues")
// files that vanish, no keys
check(queueUp(m, 8, "slow") && queueUp(m, 9) && queueUp(m, 10), "three"); try! fm.removeItem(at: root.appendingPathComponent("dump/Game 9 [\(id(9))][v0].nsp")); check(wait { m.queue.current == nil && m.queue.waiting.isEmpty && game(m, id(10)) != nil }, "goes past a missing file"); check(m.queue.problems.contains { $0.reason.contains("can't be found") }, "and says which"); m.queue.problems = []
// a restart
check(queueUp(m, 11, "slow") && queueUp(m, 12), "two"); check(wait { log().contains("start \(id(11))") }, "running"); let saved = Queue.load(); check(saved.paused && saved.waiting.map(\.title) == ["Game 11", "Game 12"], "a crash now would keep both, paused"); check(wait { m.queue.current == nil && m.queue.waiting.isEmpty }, "finish"); check(!fm.fileExists(atPath: Queue.file.path) || !m.queue.problems.isEmpty, "no queue file is left")
check(!log().contains("overlap") && log().filter { $0.hasPrefix("start") }.count == 11, "never two at once, each once"); check((try? String(contentsOf: root.appendingPathComponent("prod.keys"), encoding: .utf8)) == "k = 1", "the keys were never touched")
// covers
func pic(_ n: String, _ w: Int, _ h: Int) -> URL { let r = Cover.bitmap(w, h) { NSColor.red.setFill(); NSRect(x: 0, y: 0, width: w, height: h).fill() }; let u = root.appendingPathComponent(n); try! r.representation(using: .png, properties: [:])!.write(to: u); return u }
func px(_ i: NSImage) -> NSBitmapImageRep { i.representations.compactMap { $0 as? NSBitmapImageRep }.first! }
let cg1 = game(m, id(1))!; check(m.cover(cg1) == nil && wait { m.cover(cg1) != nil }, "a cover is made in the background"); check(px(m.cover(cg1)!).pixelsWide == 312 && px(m.cover(cg1)!).pixelsHigh == 372, "at the size it is shown")
let band = px(m.cover(cg1)!); check(band.pixelsHigh == 372, "shape")
m.setArt(cg1, pic("tall.png", 900, 1200)); check(m.hasArt(cg1) && wait { m.cover(cg1) != nil }, "a chosen picture"); let red = px(m.cover(cg1)!).colorAt(x: 150, y: 200)!; check(red.redComponent > 0.8 && red.greenComponent < 0.3, "fills the cover"); check(NSImage(contentsOf: Cover.custom(cg1))!.representations[0].pixelsHigh == 640, "kept small")
m.message = nil; m.setArt(cg1, put("bad.png", "not a picture")); check(m.message != nil && m.hasArt(cg1), "a bad picture changes nothing"); m.message = nil; m.setArt(cg1, pic("strip.png", 3000, 20)); check(m.message != nil, "nor a sliver"); m.message = nil
for (n, w, h) in [("wide", 800, 300), ("square", 500, 500), ("tiny", 3, 4)] { m.dropped([pic(n + ".png", w, h)], on: cg1); check(wait { m.cover(cg1) != nil } && px(m.cover(cg1)!).pixelsHigh == 372, "dropped: " + n) }
m.clearArt(cg1); check(!m.hasArt(cg1) && wait { m.cover(cg1) != nil }, "back to its own"); check(Cover.custom(Game(url: root, name: "x", titleID: "../../evil")).path.hasPrefix(root.path + "/Artwork/"), "never outside the artwork folder")
// choosing a game
m.select(cg1); check(m.chosen?.id == cg1.id, "a click chooses"); m.select(cg1); check(m.chosen?.id == cg1.id && m.runningIDs.isEmpty, "a second click neither closes nor plays"); check(wait { m.size(cg1) != nil } && m.size(cg1)! > 0, "measured in the background"); let cg3 = game(m, id(3))!; m.select(cg3); check(m.chosen?.id == cg3.id, "another"); let gone3 = m.games; m.games.removeAll { $0.id == cg3.id }; check(m.chosen == nil, "a game that is gone is not chosen"); m.games = gone3; m.selected = nil
// the art fills the cover: only a thin edge is colour
let sq = Cover.bitmap(600, 600) { NSColor.green.setFill(); NSRect(x: 0, y: 0, width: 600, height: 600).fill(); NSColor.red.setFill(); for k in stride(from: 0, to: 600, by: 20) { NSRect(x: 0, y: k, width: 600, height: 10).fill() } }; let si = NSImage(size: NSSize(width: 600, height: 600)); si.addRepresentation(sq); let cv = px(Cover.make(art: si)); var sharp = 0; for y in 1..<372 { let a = cv.colorAt(x: 156, y: y)!, b = cv.colorAt(x: 156, y: y - 1)!; if abs(a.redComponent - b.redComponent) > 0.15 { sharp = y } }; check(sharp > 372 * 88 / 100, "sharp art reaches \(sharp) of 372")
// a big library
for n in 0..<300 { m.library.addRom(Rom(id: "nes:\(n)", name: "Old Game \(n)", console: "nes", path: "/x/\(n).nes")) }; m.reload(); let t0 = Date(); var worst = 0.0; for g in m.games { let a = Date(); _ = m.cover(g); worst = max(worst, Date().timeIntervalSince(a)) }; let held = Date().timeIntervalSince(t0); check(wait(60) { m.games.allSatisfy { m.cover($0) != nil } }, "300 covers"); print(String(format: "300 covers: window held %.0f ms in all, %.1f ms at worst, ready in %.1f s", held * 1000, worst * 1000, Date().timeIntervalSince(t0))); check(worst < 0.1, "no long hold")
check(Notify.text(done: "A", failed: nil, left: 2, problems: 0) == ("A is ready", "2 more to go.") && Notify.text(done: "A", failed: nil, left: 0, problems: 0).1 == "Open Docked to play." && Notify.text(done: nil, failed: "B", left: 1, problems: 0).0 == "B could not be converted" && Notify.text(done: "A", failed: nil, left: 0, problems: 2).1 == "2 games need your attention.", "notices")
UserDefaults.standard.removePersistentDomain(forName: ProcessInfo.processInfo.processName)
print("queue and clean-up, whole: \(np) passed, \(nf) failed"); exit(nf == 0 ? 0 : 1)
